flowchart TD
  A["Palabra + s (plural o he, she, it)"] --> B{"¿Termina en sonido silbante? s, z, sh, ch, j"}
  B -->|"sí"| C["/ɪz/ una sílaba más: boxes, brushes, watches, bridges, pages"]
  B -->|"no"| D{"¿El último sonido es sordo? p, t, k, f, th"}
  D -->|"sí"| E["/s/: cups, cats, books, laughs, months"]
  D -->|"no"| F["/z/: dogs, days, bees, pens, cows"]

flowchart TD
  A["Palabra + ed (pasado o participio)"] --> B{"¿Termina en sonido t o d?"}
  B -->|"sí"| C["/ɪd/ una sílaba más: painted, ended, pointed, needed, rested"]
  B -->|"no"| D{"¿El último sonido es sordo? p, k, f, s, sh, ch"}
  D -->|"sí"| E["/t/: stopped, walked, laughed, kissed, pushed, watched"]
  D -->|"no"| F["/d/: played, turned, rained, moved, opened, named"]

flowchart TD
  A["Quieres decir lo contrario de una cualidad"] --> B{"¿Tiene un opuesto en la lista?"}
  B -->|"sí"| C["Úsalo: good → bad, sweet → bitter, wet → dry"]
  B -->|"no"| D{"¿Es possible o probable?"}
  D -->|"sí"| E["im-: impossible, improbable"]
  D -->|"no"| F{"¿Es regular o responsible?"}
  F -->|"sí"| G["ir-: irregular, irresponsible"]
  F -->|"no"| H["Casi siempre un-: unhappy, unkind, unable, uncertain, unnecessary"]
  H --> I["Ojo: complete → incomplete, normal → abnormal"]
